save(366,dict(paragraphs=['Neha Bhandarkar is a poet, author and translator who writes in Marathi, Hindi and English. Her contributor biography in Our Poetry Archive identifies her with Nagpur and describes her work as a Marathi newspaper columnist. The Guntur International Poetry Festival lists her book Hues of Fusion among its festival releases.','In her Kabita Live poem ‘Worthy Meeting’, an encounter becomes an exchange of gifts with the natural world. Clouds, rain, sunlight and a rainbow take on the qualities of clothing, music and adornment. The poem gathers these changing seasons into a wish to return, making the meeting both intimate and expansive.'],sources=[source('Our Poetry Archive — Neha Bhandarkar, April 2023','https://ourpoetryarchive.blogspot.com/2023/04/neha-bhandarkar.html',['Trilingual author and translator; Marathi newspaper columnist; Nagpur identification.']),source('Guntur International Poetry Festival — Books Released at Our Fests','https://www.gipf.club/books-releasing-at-12-gipf',['Hues of Fusion by Neha Bhandarkar listed with cover among festival releases.'])],books=[dict(title='Hues of Fusion',detail='Listed among the Guntur International Poetry Festival’s book releases.',url='https://www.gipf.club/books-releasing-at-12-gipf')],identity_match='Exact full name, distinctive Marathi/Hindi/English writing and translator role match captured biography. Public contributor biography further parallels the captured multilingual publication/broadcast history; only modest corroborated details adopted.',poems_read=[dict(id=482,title='WORTHY MEETING',basis='Full original English text; gifts from cloud, rain, sunlight, cuckoo music, waterfall anklets, rainbow and cyclical meeting.')],limitations=['No current book total asserted: dated biographies give 13, 15 and 16 books.','Captured awards, academic syllabus, ambassador role and detailed broadcast claims not repeated without institutional confirmation.','Festival page confirms book and author, but no date, publisher or genre asserted in card.','Weather and intimacy are literary interpretation, not biographical events.'],research_leads=[dict(url='https://www.innerchildpress.com/resources/WHWP%202024%20GRATIS.pdf',access='search_index_excerpt',finding='Publisher anthology bio describes trilingual author/translator and 15 books; dated count not presented as current.'),dict(url='https://www.innerchildpress.com/resources/Changing%20the%20World%20GRATIS.pdf',access='search_index_excerpt',finding='Publisher anthology bio gives Nagpur and 16 books; supports identity, count omitted.'),dict(url='https://journals.sagepub.com/doi/10.1177/0021989420962768',access='search_index_excerpt',finding='2020 bibliography India by Payal Nagpal/Shyamala Narayan lists Hues of Fusion, Authorspress, as short stories; genre/publisher remain follow-up rather than reader claims.')],next_action='Author/editor review; verify complete bibliography and award records separately before extending the profile.'))
